from rich.console import Console
from rich.segment import Segment
from unittest.mock import MagicMock
import io

def test_broken_pipe_write_clears_buffer():
    mock_file = MagicMock(spec=io.TextIOBase)
    mock_file.write.side_effect = BrokenPipeError()

    console = Console(file=mock_file)

    # Populate buffer with a Segment
    console._buffer.append(Segment("test"))

    try:
        console._check_buffer()
    except BrokenPipeError:
        print("Failed: BrokenPipeError was raised")
        return

    if len(console._buffer) == 0:
        print("Success: Buffer cleared after BrokenPipeError during write")
    else:
        print(f"Failed: Buffer not cleared, size: {len(console._buffer)}")

def test_broken_pipe_flush_clears_buffer():
    mock_file = MagicMock(spec=io.TextIOBase)
    mock_file.flush.side_effect = BrokenPipeError()

    console = Console(file=mock_file)
    console._buffer.append(Segment("test"))

    try:
        console._check_buffer()
    except BrokenPipeError:
        print("Failed: BrokenPipeError was raised")
        return

    if len(console._buffer) == 0:
        print("Success: Buffer cleared after BrokenPipeError during flush")
    else:
        print(f"Failed: Buffer not cleared, size: {len(console._buffer)}")

if __name__ == "__main__":
    test_broken_pipe_write_clears_buffer()
    test_broken_pipe_flush_clears_buffer()
